<script lang="ts">
 import {onMount} from "svelte";
 import {api} from "./api";
 let {onSecretState=(_:boolean)=>{}}=$props<{onSecretState?:(open:boolean)=>void}>();
 let data=$state<any>(null);let pending=$state<any[]>([]);let audit=$state<any[]>([]);let selected=$state<any>(null);let last=$state<any>(null);let error=$state("");let message=$state("");let busy=$state(false);let name=$state("Hermes");let endpoint=$state("");let scopes=$state<string[]>([]);let token=$state("");let showToken=$state(false);let config=$state("");let testToken=$state("");let reason=$state("");let alive=true;
 const stateLabel=(value:string)=>({pending:"待你批准",saved:"已保存",saved_warning:"已保存，需检查",stale:"已失效",rejected:"已拒绝",needs_review:"中断待核对",applying:"中断待核对",failed:"未完成",recorded:"已记录"}[value]||value);
 const publishLabel=(value:string)=>({not_applied:"尚未应用",draft_only:"仅草稿／私人保存",queued:"网站生成中",published:"已上线",superseded:"后续内容已更新",blocked:"撤回后等待安全版本",failed:"构建失败，内容仍已保存",queue_failed:"内容已保存，构建未排队"}[value]||value);
 const labels:Record<string,string>={title:"标题",description:"摘要",date:"日期",publish:"公开",slug:"链接名称",category:"分类",tags:"标签",cover_image:"封面",toc:"目录",template:"模板",source_url:"来源",weight:"排序权重",body:"Markdown正文",display:"阅读展示",appearance:"配色与外观",wallpaper:"壁纸",navigation:"导航",sidebar:"侧栏",music:"音乐",local:"本地歌曲",meting:"外部歌单",volume:"音量",playMode:"循环方式",showLyrics:"显示歌词",announcement:"公告",friends:"友链",booknav:"书签",gallery:"相册",footer:"页脚",fonts:"字体",pages:"页面开关",themeColor:"主题色",hue:"色相",name:"名称",url:"地址",enable:"启用",id:"标识",server:"平台"};
 function flatten(value:any,path="",out:Record<string,string>={}):Record<string,string>{if(value===null||value===undefined){if(path)out[path]="未设置";}else if(Array.isArray(value)){if(!value.length)out[path]="空列表";value.forEach((v,i)=>flatten(v,`${path} [${i+1}]`,out));}else if(typeof value==="object"){const entries=Object.entries(value);if(!entries.length&&path)out[path]="主题默认";for(const [k,v] of entries)flatten(v,path?path+" / "+(labels[k]||k):labels[k]||k,out);}else out[path]=typeof value==="boolean"?(value?"是":"否"):String(value)||"空";return out;}
 const differences=()=>{const before=flatten(selected?.before),after=flatten(selected?.after);return [...new Set([...Object.keys(before),...Object.keys(after)])].filter(key=>before[key]!==after[key]).map(key=>({key,before:before[key]||"未设置",after:after[key]||"未设置"}));};
 async function load(){const [creds,proposals,history]=await Promise.all([api("/integrations"),api("/approvals"),api("/audit")]);data=creds;pending=proposals.items;audit=history.items;if(!endpoint)endpoint=location.origin+"/mcp";if(!scopes.length)scopes=[...creds.default_scopes];}
 async function action(fn:()=>Promise<void>){busy=true;error="";message="";try{await fn();await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function create(){await action(async()=>{const result=await api("/integrations","POST",{revision:data.revision,name,endpoint,scopes});token=result.token;testToken=token;config=result.config;onSecretState(true);message=result.message;});}
 function hideSecret(){token="";testToken="";showToken=false;onSecretState(false);}
 async function copy(text:string){try{await navigator.clipboard.writeText(text);message="已复制。";}catch{error="浏览器不允许自动复制，请选择下方文字手动复制。";showToken=true;}}
 async function revoke(item:any){if(!confirm(`撤销「${item.name}」？Hermes将不能再使用此凭据；未批准候选也不能继续批准。`))return;await action(async()=>{await api(`/integrations/${item.id}`,"DELETE",{revision:data.revision});message="凭据已撤销。";});}
 async function test(){await action(async()=>{const result=await api("/integrations/test","POST",{token:testToken});message=result.message+" 检查范围："+result.scope;});}
 async function inspect(item:any){error="";reason="";try{selected=await api(`/approvals/${item.id}`);}catch(e){error=(e as Error).message;}}
 async function decide(approve:boolean){if(!selected)return;const operation=selected.operation;if(approve&&!confirm("确认应用这个具体修改？公开内容会进入构建队列，构建成功后才上线。"))return;await action(async()=>{last=await api(`/approvals/${operation.id}/${approve?"approve":"reject"}`,"POST",{revision:operation.revision,...(!approve?{reason}:{})});selected=null;message=approve?"修改已保存。请看下方实际发布状态。":"候选已拒绝，网站未修改。";});}
 onMount(()=>{void load().catch(e=>error=e.message);const timer=setInterval(async()=>{if(busy)return;try{const list=await api("/approvals");if(alive)pending=list.items;if(last?.public_applied&&!["published","superseded"].includes(last.publication_status)){const detail=await api(`/approvals/${last.id}`);if(alive)last=detail.operation;}}catch{}},3000);return()=>{alive=false;clearInterval(timer);hideSecret();};});
</script>
<section class="card-base panel stack"><h1>助手与审批</h1><p class="muted">让 Hermes 帮你整理草稿；公开修改由你决定。它不需要管理员密码，也不需要访问网站数据卷。</p>
 {#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice" role="status">{message}</div>{/if}
 {#if last}<div class="notice"><strong>{stateLabel(last.status)} · {publishLabel(last.publication_status)}</strong>{#if last.error}<p>{last.error}</p>{/if}</div>{/if}
 <div class="row spread"><h2>等待你的决定 <span class="pill">{pending.length}</span></h2><button disabled={busy} onclick={()=>load().catch(e=>error=e.message)}>刷新</button></div>
 {#if !pending.length}<p class="muted">没有待审批修改。写草稿不打扰你；发布、撤回和外观变更会出现在这里。</p>{/if}
 {#each pending as item}<div class="item"><div class="grow"><strong>{item.title}</strong><p class="muted">{item.actor} · {new Date(item.created).toLocaleString()} · {item.kind==="theme"?"外观／模块":"公开内容"}</p></div><button disabled={busy} onclick={()=>inspect(item)}>查看差异</button></div>{/each}
 {#if selected}<article class="stack proposal"><div class="row spread"><h2>{selected.operation.title}</h2><button onclick={()=>selected=null}>关闭差异</button></div><p class="muted">只应用下列具体候选。目标或主题版本变化后，需要助手重新读取并提交，不能覆盖你的新修改。</p>
  {#each differences() as row}<div class="diff"><h3>{row.key}</h3><div class="diff-values"><div><small class="muted">修改前</small><pre tabindex="0">{row.before}</pre></div><div><small class="muted">修改后</small><pre tabindex="0">{row.after}</pre></div></div></div>{/each}
  {#if selected.operation.status==="pending"}<label>拒绝说明（可选）<input bind:value={reason} maxlength="1000" placeholder="例如：保留原来的标题，再改正文" /></label><div class="row"><button class="primary" disabled={busy} onclick={()=>decide(true)}>批准这个修改</button><button disabled={busy} onclick={()=>decide(false)}>拒绝候选</button></div>{:else}<p class="notice">{stateLabel(selected.operation.status)}。此记录不能再次执行；中断状态请先核对目标内容，再让助手提交新的候选。</p>{/if}
 </article>{/if}
</section>
<section class="card-base panel stack"><h2>Hermes 接入</h2><p class="muted">默认可读公开内容和草稿、能写草稿；发布和外观修改必须审批。笔记与 Wiki 不默认授权，勾选后相关内容可以进入 Hermes 的模型上下文。</p>
 {#if data}<form class="stack" onsubmit={e=>{e.preventDefault();create();}}><label>助手名称<input bind:value={name} required placeholder="Hermes" /></label><label>Hermes 连接地址<input type="url" bind:value={endpoint} required placeholder="https://你的博客域名/mcp" /></label><p class="muted">推荐使用博客的 HTTPS 域名。HTTP 仅用于同机或可信 Docker 网络；凭据绑定此地址，代理应保留 Host。</p><fieldset class="scope-list"><legend>允许的范围</legend>{#each Object.entries(data.scopes) as [scope,description]}<label><input type="checkbox" value={scope} bind:group={scopes} /><span>{String(description)}</span></label>{/each}</fieldset><button class="primary" disabled={busy||!!token}>创建专用凭据</button></form>{/if}
 {#if token}<div class="notice stack"><h3>这次是唯一显示凭据的机会</h3><label>一次性凭据<input type={showToken?"text":"password"} value={token} readonly autocomplete="off" /></label><div class="row"><button onclick={()=>copy(token)}>复制凭据</button><button onclick={()=>showToken=!showToken}>{showToken?"隐藏字符":"显示字符"}</button><button onclick={hideSecret}>我已保存，清除此处显示</button></div><p>把它保存到 Hermes 的私密环境文件 <code>~/.hermes/.env</code>，变量名为 <code>AIGONI_MCP_TOKEN</code>。不要写进公开文章或主题源码。</p><h3>Hermes 配置</h3><p>将以下内容合并到 <code>~/.hermes/config.yaml</code> 的 <code>mcp_servers</code>，不要覆盖其他服务；保存后重启 Hermes。</p><pre tabindex="0">{config}</pre><button onclick={()=>copy(config)}>复制连接配置</button></div>{/if}
 <details><summary>检查协议与凭据</summary><div class="stack"><label>待检查的助手凭据<input type="password" bind:value={testToken} autocomplete="off" /></label><button disabled={busy||!testToken} onclick={test}>检查本应用中的 MCP 连接</button><p class="muted">检查凭据和协议初始化，不发起模型调用，也不检查 Hermes 宿主机的网络或证书。真实工具发现请在 Hermes 重启后确认。</p></div></details>
 {#if data}<h3>已授权的助手</h3>{#each data.items as item}<div class="item"><div class="grow"><strong>{item.name} {item.revoked?"· 已撤销":""}</strong><p class="muted wrap">{item.endpoint}</p><p class="muted">{item.scopes.join(" · ")}</p><small class="muted">最近使用：{item.last_used?new Date(item.last_used).toLocaleString():"尚未连接"}</small></div>{#if !item.revoked}<button disabled={busy} onclick={()=>revoke(item)}>撤销</button>{/if}</div>{/each}{/if}
</section>
<section class="card-base panel stack"><h2>最近操作</h2><p class="muted">显示最近100条。记录保存在私人数据区，不进入公开博客、搜索索引或数据备份。</p>{#if !audit.length}<p class="muted">还没有助手操作。</p>{/if}{#each audit as item}<div class="item"><div class="grow"><strong>{item.title}</strong><p class="muted">{item.actor} · {new Date(item.created).toLocaleString()}</p><small>{stateLabel(item.status)}{#if item.kind==="public"||item.kind==="theme"} · {publishLabel(item.publication_status)}{/if}</small>{#if item.error}<p>{item.error}</p>{/if}</div>{#if item.kind==="public"||item.kind==="theme"}<button onclick={()=>inspect(item)}>详情</button>{/if}</div>{/each}</section>
<style>.scope-list{border:0;padding:0;display:grid;gap:.7rem}.scope-list legend{margin-bottom:.7rem;font-weight:600}.scope-list label{display:flex;gap:.7rem;align-items:flex-start}.scope-list input{width:1.15rem;height:1.15rem;flex:none;margin-top:.2rem;accent-color:var(--primary)}pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:.8rem;background:var(--btn-regular-bg);border-radius:.7rem;max-height:26rem;overflow:auto;font:inherit}h3{font-size:1rem}.diff-values{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:1rem}.diff{padding:.6rem 0;border-bottom:1px solid var(--line-divider)}.proposal{padding:1rem;border:1px solid var(--line-divider);border-radius:1rem}.wrap{overflow-wrap:anywhere}@media(max-width:600px){.diff-values{grid-template-columns:1fr}}</style>
